// Finds elements that hide overflow and actually cut off a descendant (box or focus ring/shadow).
const findClipped = (scopeSelector) => page.evaluate((sel) => {
  const out = [];
  const roots = sel ? Array.from(document.querySelectorAll(sel)) : [document.body];
  const seen = new Set();
  const check = (el) => {
    if (!el || seen.has(el) || el === document.documentElement || el === document.body) return;
    seen.add(el);
    const cs = getComputedStyle(el);
    const clips = (v) => v === 'hidden' || v === 'clip';
    if (!(clips(cs.overflowX) || clips(cs.overflowY))) return;
    if (cs.textOverflow === 'ellipsis') return;
    const r = el.getBoundingClientRect();
    if (r.width === 0 || r.height === 0) return;
    for (const c of el.querySelectorAll('*')) {
      const cr = c.getBoundingClientRect();
      if (cr.width === 0 || cr.height === 0) continue;
      const ccs = getComputedStyle(c);
      if (ccs.position === 'absolute' || ccs.position === 'fixed') continue;
      if (cr.left < r.left - 0.5 || cr.right > r.right + 0.5 || cr.top < r.top - 0.5 || cr.bottom > r.bottom + 0.5) {
        out.push((el.getAttribute('class') || el.tagName) + ' clips ' + (c.getAttribute('class') || c.tagName));
        return;
      }
    }
  };
  for (const root of roots) {
    let p = root;
    for (let i = 0; i < 4 && p; i++, p = p.parentElement) check(p);
    for (const d of root.querySelectorAll('*')) check(d);
  }
  return out;
}, scopeSelector);

// Landing page (signed out)
await page.goto('/login');
await expect(page).toHaveURL(/\/login/);
const landingClipped = await findClipped(null);
expect(landingClipped).toEqual([]);

// Radar mode switch
await page.goto('/ops/radar');
await expect(page).toHaveURL(/\/ops\/radar/);
const switchGroup = page.getByRole('tablist').or(page.getByRole('radiogroup')).first();
await expect(switchGroup).toBeVisible();
const switchClipped = await findClipped('[role="tablist"], [role="radiogroup"]');
expect(switchClipped).toEqual([]);
